-- Business assets cell (business-assets), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA business_assets;

CREATE FUNCTION business_assets.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE business_assets.assets (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    asset_type               text NOT NULL CHECK (asset_type IN ('content', 'code', 'audience', 'data', 'brand', 'system', 'network', 'ip')),
    description              text,
    url                      text,
    platform                 text,
    status                   text NOT NULL DEFAULT 'planning' CHECK (status IN ('planning', 'building', 'active', 'maintenance', 'archived')),
    monthly_value            double precision CHECK (monthly_value IS NULL OR (monthly_value >= 0)),
    total_value              double precision CHECK (total_value IS NULL OR (total_value >= 0)),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    launched_at              date,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX assets_legacy ON business_assets.assets (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX assets_asset_type ON business_assets.assets (workspace_id, asset_type);
CREATE INDEX assets_status ON business_assets.assets (workspace_id, status);

CREATE TABLE business_assets.asset_metrics (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    asset_id                 bigint NOT NULL,
    metric_date              date NOT NULL,
    views                    integer NOT NULL DEFAULT 0 CHECK (views >= 0),
    subscribers              integer NOT NULL DEFAULT 0 CHECK (subscribers >= 0),
    revenue                  double precision NOT NULL DEFAULT 0 CHECK (revenue >= 0),
    engagement_rate          double precision CHECK (engagement_rate IS NULL OR (engagement_rate >= 0)),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, asset_id, metric_date),
    FOREIGN KEY (workspace_id, asset_id) REFERENCES business_assets.assets (workspace_id, id)
);
CREATE UNIQUE INDEX asset_metrics_legacy ON business_assets.asset_metrics (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX asset_metrics_asset_id ON business_assets.asset_metrics (workspace_id, asset_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE business_assets.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('asset', 'asset-metric')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE business_assets.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON business_assets.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['assets', 'asset_metrics', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE business_assets.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE business_assets.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON business_assets.%I'
                       ' USING (workspace_id = business_assets.current_workspace())'
                       ' WITH CHECK (workspace_id = business_assets.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA business_assets TO business_assets_api;
GRANT EXECUTE ON FUNCTION business_assets.current_workspace() TO business_assets_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON business_assets.assets, business_assets.asset_metrics TO business_assets_api;
GRANT USAGE ON SEQUENCE business_assets.assets_id_seq, business_assets.asset_metrics_id_seq TO business_assets_api;
GRANT SELECT, INSERT ON business_assets.create_keys TO business_assets_api;
GRANT SELECT, INSERT ON business_assets.outbox TO business_assets_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON business_assets.outbox TO business_assets_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON business_assets.outbox TO business_assets_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA business_assets TO business_assets_publisher;
GRANT SELECT ON business_assets.outbox TO business_assets_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON business_assets.outbox TO business_assets_publisher;
